window.PROMPTS = [{"id": "01-A", "category": "一、品牌識別與社群行銷", "item": 1, "title": "社群貼文圖片", "variant": "A", "label": "優化版：療癒日常", "prompt": "請製作一張4:5直式Instagram貼文圖片，主題為「日常療癒生活」。以晨光灑落的木桌為場景，擺放陶瓷咖啡杯、翻開的書、亞麻布與一小束植物；使用奶油白、燕麥色及鼠尾草綠，光線柔和，陰影細緻，帶有輕微紙張紋理。主體集中在下方三分之二，上方保留約25%乾淨留白供短文使用，營造安靜、溫暖、有生活感的文青氛圍。", "fields": [], "image": "assets/images/01-A.webp", "imageStatus": "complete"}, {"id": "01-B", "category": "一、品牌識別與社群行銷", "item": 1, "title": "社群貼文圖片", "variant": "B", "label": "新增一：週末慢生活", "prompt": "請製作一張4:5直式社群圖片，主題為「把週末還給自己」。用手繪水彩描繪窗邊閱讀角落、柔軟抱枕、盆栽與冒著熱氣的茶杯；採米白、淺杏及霧藍色，加入自然暈染與棉紙質感。畫面採對角線構圖，右上留出標題「慢一點，也很好」的位置，文字簡短清楚，整體適合生活品牌與閱讀社群分享。", "fields": [], "image": "assets/images/01-B.webp", "imageStatus": "complete"}, {"id": "01-C", "category": "一、品牌識別與社群行銷", "item": 1, "title": "社群貼文圖片", "variant": "C", "label": "新增二：城市下班療癒", "prompt": "請設計一張1:1正方形社群貼文，主題為「下班後的小幸福」。描繪傍晚城市公寓中的餐桌、暖色小燈、簡單晚餐與窗外模糊夜景，使用暖橘、奶茶棕與深藍形成柔和對比。以電影感攝影呈現，避免過度飽和；下方保留一條乾淨文案區，加入「今天辛苦了」短句，讓焦點落在平凡而舒適的生活片刻。", "fields": [], "image": "assets/images/01-C.webp", "imageStatus": "complete"}, {"id": "02-A", "category": "一、品牌識別與社群行銷", "item": 2, "title": "YouTube縮圖", "variant": "A", "label": "優化版：AI提升效率", "prompt": "請設計一張16:9橫式資訊型YouTube縮圖，主題為「AI提升工作效率」。左側以大字呈現「AI工作加速」，右側安排原創人物操作筆電，背景加入簡化的自動化流程、發光節點與文件圖示。使用深藍、亮黃及白色，標題不超過兩行；人物表情專注而有驚喜感，保留右下角空間避免關鍵資訊被時間標示遮住，縮小後仍能辨識主題。", "fields": [], "image": "assets/images/02-A.webp", "imageStatus": "complete"}, {"id": "02-B", "category": "一、品牌識別與社群行銷", "item": 2, "title": "YouTube縮圖", "variant": "B", "label": "新增一：前後對照", "prompt": "請製作16:9橫式YouTube縮圖，主題為「AI協助整理工作」。左右分割構圖：左邊是凌亂文件與疲憊工作者，右邊是整齊任務面板與從容工作者，以同一人物維持連續性。左側灰藍、右側亮青綠，中間用一道發光分界連接，加入大標「工作整理術」與小標「AI怎麼幫忙？」。圖示少而明確，不加入未經證實的效率數字。", "fields": [], "image": "assets/images/02-B.webp", "imageStatus": "complete"}, {"id": "02-C", "category": "一、品牌識別與社群行銷", "item": 2, "title": "YouTube縮圖", "variant": "C", "label": "新增二：工具實測", "prompt": "請設計16:9橫式YouTube縮圖，主題為「三種AI工具實測」。畫面中央放置原創主持人半身，周圍以三張不同色彩的功能卡呈現寫作、簡報與資料整理；不使用未提供的工具Logo。背景是乾淨科技工作室，以紫色、青色與白色形成鮮明對比，標題為「AI工具實測」，下方小字「哪種最適合你？」；避免密集小字與複雜介面。", "fields": [], "image": "assets/images/02-C.webp", "imageStatus": "complete"}, {"id": "03-A", "category": "一、品牌識別與社群行銷", "item": 3, "title": "EDM行銷主圖／廣告Banner", "variant": "A", "label": "優化版：會員限定優惠", "prompt": "請設計3:2橫式品牌EDM主圖，主題為「會員限定優惠」。左側安排主標「會員專屬禮遇」、副標【優惠內容】及清楚的行動按鈕區【按鈕文字】；右側展示【商品或禮盒】。使用米白、品牌主色與少量金色，柔和棚拍光、細緻陰影，閱讀順序由標題到商品再到按鈕。優惠日期、折扣及條件僅使用提供的文字，不自行新增。", "fields": ["優惠內容", "按鈕文字", "商品或禮盒"], "image": "assets/images/03-A.webp", "imageStatus": "complete"}, {"id": "03-B", "category": "一、品牌識別與社群行銷", "item": 3, "title": "EDM行銷主圖／廣告Banner", "variant": "B", "label": "新增一：新品預購Banner", "prompt": "請設計3:1橫幅廣告，主題為【新品名稱】預購。商品置於右側三分之一，左側保留清楚的標題、副標及「立即預購」按鈕示意，背景使用低彩度漸層與細緻幾何光影。配色依【品牌色】設定，確保小尺寸仍可辨識商品與主要訊息；預購日期與價格依提供內容呈現，不放入無關促銷貼紙。", "fields": ["新品名稱", "品牌色"], "image": "assets/images/03-B.webp", "imageStatus": "complete"}, {"id": "03-C", "category": "一、品牌識別與社群行銷", "item": 3, "title": "EDM行銷主圖／廣告Banner", "variant": "C", "label": "新增二：節慶禮物提案", "prompt": "請製作4:5直式節慶促銷主視覺，主題為「把心意送到」。以【品牌禮盒】為中心，搭配緞帶、紙卡與符合【節慶】的少量裝飾，採暖白、酒紅及霧金配色。上方放主標，中段呈現禮盒與材質，下方安排【優惠資訊】和行動文字。構圖精緻但不擁擠，商品包裝文字沿用參考圖，避免虛構品牌與價格。", "fields": ["品牌禮盒", "節慶", "優惠資訊"], "image": "assets/images/03-C.webp", "imageStatus": "complete"}, {"id": "04-A", "category": "一、品牌識別與社群行銷", "item": 4, "title": "活動海報設計", "variant": "A", "label": "優化版：科技論壇", "prompt": "請設計A4直式科技論壇海報，主題為【論壇名稱】。使用黑色、霧金與少量冷白，中央以抽象資料網絡、光線與幾何結構建立主視覺；上方大標題，中段副標及【講者資訊】，下方清楚列出【日期、時間、地點、報名方式】。採現代無襯線字體風格及有秩序的網格排版，資訊區保持高對比，預留QR碼位置但不生成假的可掃描碼。", "fields": ["論壇名稱", "講者資訊", "日期、時間、地點、報名方式"], "image": "assets/images/04-A.webp", "imageStatus": "complete"}, {"id": "04-B", "category": "一、品牌識別與社群行銷", "item": 4, "title": "活動海報設計", "variant": "B", "label": "新增一：校園創意工作坊", "prompt": "請設計A4直式「AI創意實作工作坊」海報，對象為高中學生。使用明亮藍、珊瑚橘與奶油白，搭配原創學生插畫、筆電、燈泡及創意草稿。標題活潑醒目，下方依序呈現【活動內容、日期、地點、參加對象、報名資訊】，以圓角區塊整理，留白充足，人物表情自然，整體有校園青春感且方便公告欄閱讀。", "fields": ["活動內容、日期、地點、參加對象、報名資訊"], "image": "assets/images/04-B.webp", "imageStatus": "complete"}, {"id": "04-C", "category": "一、品牌識別與社群行銷", "item": 4, "title": "活動海報設計", "variant": "C", "label": "新增二：文藝市集", "prompt": "請設計A4直式文藝市集海報，主題為【市集名稱】。採復古活版印刷風，使用奶油紙色、磚紅與森林綠，主視覺包含手作攤位、書籍、植物及咖啡。上方安排弧形標題，中段以插畫建立熱鬧氛圍，下方用清楚區塊列出【日期、時間、地點、特色活動】；紙張顆粒只作背景，不降低文字可讀性。", "fields": ["市集名稱", "日期、時間、地點、特色活動"], "image": "assets/images/04-C.webp", "imageStatus": "complete"}, {"id": "05-A", "category": "一、品牌識別與社群行銷", "item": 5, "title": "社群輪播圖", "variant": "A", "label": "優化版：AI工具推薦封面", "prompt": "請設計4:5直式Instagram輪播封面，主題為「AI工具推薦」。以白色、深藍及亮青色建立簡潔科技感，中央安排大型標題，下方以三個清楚圖示代表寫作、簡報與研究；加入小字「找到適合你的工作夥伴」。上方預留品牌識別，下方放頁碼「01」與滑動提示，留出一致邊界，避免使用未提供的工具Logo或虛構功能。", "fields": [], "image": "assets/images/05-A.webp", "imageStatus": "complete"}, {"id": "05-B", "category": "一、品牌識別與社群行銷", "item": 5, "title": "社群輪播圖", "variant": "B", "label": "新增一：五頁教學輪播", "prompt": "請依【教學內容】設計五張4:5直式輪播圖，分別為封面、問題情境、操作方法、示例及重點回顧。每張單獨輸出，維持相同標題位置、品牌色、字體層級與頁碼樣式。採奶油白、深綠及橘色點綴，每頁只呈現一個核心觀念，搭配簡潔插畫與少量文字；不要將五張縮成一張拼貼總覽。", "fields": ["教學內容"], "image": "assets/images/05-B.webp", "imageStatus": "complete"}, {"id": "05-C", "category": "一、品牌識別與社群行銷", "item": 5, "title": "社群輪播圖", "variant": "C", "label": "新增二：常見迷思輪播", "prompt": "請設計四張4:5直式社群輪播，主題為【主題】的三個常見迷思，依序呈現封面及三組「迷思／釐清」。使用深紫、淡紫與白色，左右分欄清楚區分兩種說法，以原創人物對話與簡單符號輔助。每張加入一致頁碼與品牌位置，文字依提供內容呈現，避免用紅綠顏色作為唯一辨識方式。", "fields": ["主題"], "image": "assets/images/05-C.webp", "imageStatus": "complete"}, {"id": "06-A", "category": "一、品牌識別與社群行銷", "item": 6, "title": "品牌Logo概念圖", "variant": "A", "label": "優化版：三種識別方向", "prompt": "請為【品牌名稱】及【品牌理念】設計三張獨立Logo概念稿：極簡幾何、科技感、精品感。每張1:1比例、白色背景、標誌置中，先呈現黑白版本，再附小型品牌色版本；符號應具有清楚輪廓、適度負空間與縮小後的辨識度。只使用指定品牌文字，不模仿現有品牌。設計理念另以文字說明，不塞入Logo圖內。", "fields": ["品牌名稱", "品牌理念"], "image": "assets/images/06-A.webp", "imageStatus": "complete"}, {"id": "06-B", "category": "一、品牌識別與社群行銷", "item": 6, "title": "品牌Logo概念圖", "variant": "B", "label": "新增一：自然生活品牌", "prompt": "請為【自然生活品牌名稱】設計1:1Logo概念，將葉片、晨光與字母【指定字母】整合為一個簡潔符號。使用森林綠與暖米白，線條厚度一致，避免細碎裝飾；呈現主標誌、單色版與小尺寸圖示的同版展示。整體溫暖、可靠，適合包裝與社群頭像，文字依指定品牌名呈現，另用文字解釋符號含義。", "fields": ["自然生活品牌名稱", "指定字母"], "image": "assets/images/06-B.webp", "imageStatus": "complete"}, {"id": "06-C", "category": "一、品牌識別與社群行銷", "item": 6, "title": "品牌Logo概念圖", "variant": "C", "label": "新增二：教育知識品牌", "prompt": "請為【教育品牌名稱】設計1:1Logo概念，結合翻開的書、對話框與向上成長的意象，使用深藍及明亮橘色。造型親切、簡單且具有秩序，先建立可單獨辨識的符號，再搭配品牌名稱；展示淺底與深底應用。避免把所有教育圖示堆進標誌，設計需在小尺寸仍保持清楚輪廓，理念另以文字說明。", "fields": ["教育品牌名稱"], "image": "assets/images/06-C.webp", "imageStatus": "complete"}, {"id": "07-A", "category": "一、品牌識別與社群行銷", "item": 7, "title": "品牌社群模板", "variant": "A", "label": "優化版：四種統一版型", "prompt": "請為【品牌】設計四張4:5直式社群模板概念，分別為公告、活動、引用語錄與新品發布。統一使用【品牌色】、相同邊界、品牌標誌位置及標題層級；各版保留清楚的圖片區、主標、副標與補充資訊區。以實際示範文案展示版面，每張單獨輸出，讓內容可替換且不失一致性，不將四種版型混成單一海報。", "fields": ["品牌", "品牌色"], "image": "assets/images/07-A.webp", "imageStatus": "complete"}, {"id": "07-B", "category": "一、品牌識別與社群行銷", "item": 7, "title": "品牌社群模板", "variant": "B", "label": "新增一：高中圖書館系列", "prompt": "請設計四張4:5直式高中圖書館社群模板，主題為新書推薦、閱讀活動、開館公告與學生心得。使用奶油白、墨綠及暖橘，搭配書本、閱讀燈與植物的小型插畫。固定校名區、標題區及資訊區，新書版保留書封位置，活動版保留報名位置；文字大而清楚，每張獨立輸出並維持同一視覺系統。", "fields": [], "image": "assets/images/07-B.webp", "imageStatus": "complete"}, {"id": "07-C", "category": "一、品牌識別與社群行銷", "item": 7, "title": "品牌社群模板", "variant": "C", "label": "新增二：專業顧問系列", "prompt": "請為【顧問品牌】設計四張1:1社群模板，包含知識分享、案例摘要、課程資訊與客戶常見問題。使用白色、海軍藍及柔和青綠，採清楚網格與細線圖示，保持固定頁首品牌區與頁尾資訊區。每張最多一個重點標題及三個內容區，搭配適量留白，呈現可信、俐落的專業感，示例文字使用提供資料。", "fields": ["顧問品牌"], "image": "assets/images/07-C.webp", "imageStatus": "complete"}, {"id": "08-A", "category": "一、品牌識別與社群行銷", "item": 8, "title": "社群分享語錄卡片", "variant": "A", "label": "優化版：創業與生活語錄", "prompt": "請製作4:5直式Instagram語錄卡，內容為【語錄】及【署名】。採簡約文青風，使用米白、淺灰及鼠尾草綠，背景加入淡淡窗光、葉影與紙張紋理。語錄置於中央，以自然斷行形成節奏，重點詞可放大或用單一色彩標示；署名小而清楚置於下方，畫面保留充足留白，不自行創造名人署名。", "fields": ["語錄", "署名"], "image": "assets/images/08-A.webp", "imageStatus": "complete"}, {"id": "08-B", "category": "一、品牌識別與社群行銷", "item": 8, "title": "社群分享語錄卡片", "variant": "B", "label": "新增一：閱讀摘句", "prompt": "請設計1:1閱讀摘句卡，使用我提供的【摘句、作者、書名】。背景為乾淨的奶油紙色，角落加入鉛筆、書頁與細緻手繪線條，主文字採易讀的繁體中文排版。摘句為主要焦點，作者與書名位於底部，整體像讀書筆記中的珍藏頁；不額外補寫書中內容或未提供的引言。", "fields": ["摘句、作者、書名"], "image": "assets/images/08-B.webp", "imageStatus": "complete"}, {"id": "08-C", "category": "一、品牌識別與社群行銷", "item": 8, "title": "社群分享語錄卡片", "variant": "C", "label": "新增二：行動鼓勵卡", "prompt": "請設計4:5直式鼓勵語錄卡，文案為「先完成一小步，再走向下一步」。以階梯、發芽植物與前進的小人物作為象徵，使用柔和黃、霧藍及白色，採平面插畫與清楚的大字。文字集中在上半部，插畫集中在下半部，適合學生學習與習慣養成分享，氛圍溫暖、有行動感，避免過量裝飾。", "fields": [], "image": "assets/images/08-C.webp", "imageStatus": "complete"}, {"id": "09-A", "category": "二、商品展示與企業數位視覺", "item": 9, "title": "商品形象照", "variant": "A", "label": "優化版：保養品牌官網", "prompt": "請依上傳的【商品照片】製作4:5直式高質感商品形象照，保留包裝外形、比例、標籤及品牌識別。商品置於淺米色石材平台，搭配少量亞麻布與透明玻璃，柔和窗光由左上方照入，形成細膩陰影與自然反射。畫面乾淨、焦點清楚，有保養品牌官網的生活質感；不改寫瓶身文字，不新增不存在的功效標示。", "fields": ["商品照片"], "image": "assets/images/09-A.webp", "imageStatus": "complete"}, {"id": "09-B", "category": "二、商品展示與企業數位視覺", "item": 9, "title": "商品形象照", "variant": "B", "label": "新增一：戶外清新情境", "prompt": "請依商品參考圖製作3:2橫式形象照，將【商品】放在晨光中的戶外木桌，背景為柔焦綠葉與淡色天空。使用清新綠、自然木色及白色，透過逆光表現材質輪廓，保留清楚的商品正面與包裝文字。構圖左側展示商品，右側留白供廣告文案，情境自然可信，不讓植物遮住主要標籤。", "fields": ["商品"], "image": "assets/images/09-B.webp", "imageStatus": "complete"}, {"id": "09-C", "category": "二、商品展示與企業數位視覺", "item": 9, "title": "商品形象照", "variant": "C", "label": "新增二：精品棚拍", "prompt": "請依上傳商品圖製作1:1精品棚拍視覺，商品置於深灰霧面背景前，以單側柔光及細緻輪廓光凸顯【金屬、玻璃或皮革材質】。加入一個簡潔幾何底座，使用深灰、暖白與少量金色，呈現精準、沉穩的高級感。商品比例與包裝保持一致，陰影及反射符合光源，避免過度鏡面、漂浮或扭曲。", "fields": ["金屬、玻璃或皮革材質"], "image": "assets/images/09-C.webp", "imageStatus": "complete"}, {"id": "10-A", "category": "二、商品展示與企業數位視覺", "item": 10, "title": "品牌吉祥物商品化形象", "variant": "A", "label": "優化版：絨毛玩偶商品頁", "prompt": "請依【角色參考圖】製作4:5直式品牌吉祥物絨毛玩偶展示照，保留角色輪廓、主要配色與代表性表情。呈現柔軟短絨、細緻刺繡五官、自然縫線與適度蓬鬆感，玩偶坐在淺木桌上，背景為奶油色文創商店。使用柔和自然光，搭配一張簡潔品牌吊牌，商品正面清楚，避免多餘肢體與不合理縫線。", "fields": ["角色參考圖"], "image": "assets/images/10-A.webp", "imageStatus": "complete"}, {"id": "10-B", "category": "二、商品展示與企業數位視覺", "item": 10, "title": "品牌吉祥物商品化形象", "variant": "B", "label": "新增一：鑰匙圈系列", "prompt": "請依角色參考圖設計3:2橫式文創鑰匙圈商品照，展示三種表情版本：微笑、眨眼與打氣。使用柔軟絨毛材質、刺繡細節、金屬扣環及一致品牌配色，三件商品整齊排列於暖白背景，加入小型包裝卡作尺寸對比。保留角色辨識度，光線明亮柔和，扣環與掛繩結構合理，文字僅使用【品牌名稱】。", "fields": ["品牌名稱"], "image": "assets/images/10-B.webp", "imageStatus": "complete"}, {"id": "10-C", "category": "二、商品展示與企業數位視覺", "item": 10, "title": "品牌吉祥物商品化形象", "variant": "C", "label": "新增二：桌上收藏公仔", "prompt": "請將【吉祥物】設計成1:1桌上收藏公仔商品展示，採霧面樹脂材質與圓潤造型，搭配符合【品牌主題】的小道具及簡潔底座。畫面同時呈現三分之四視角公仔與後方包裝盒，使用品牌色與乾淨棚拍光，強調塗裝邊界、材質及可愛姿態；不更改核心外形，不以絨毛材質呈現。", "fields": ["吉祥物", "品牌主題"], "image": "assets/images/10-C.webp", "imageStatus": "complete"}, {"id": "11-A", "category": "二、商品展示與企業數位視覺", "item": 11, "title": "商業簡報封面", "variant": "A", "label": "優化版：新服務提案", "prompt": "請製作16:9橫式商業簡報封面，主題為【新服務提案名稱】。使用深藍、白色與低彩度青綠，左側放主標題、副標【服務價值】及【公司、日期】，右側以現代曲線、半透明幾何與服務相關圖示形成抽象主視覺。採顧問公司式網格排版，標題醒目，留白充足，不加入密集數據或無關裝飾。", "fields": ["新服務提案名稱", "服務價值", "公司、日期"], "image": "assets/images/11-A.webp", "imageStatus": "complete"}, {"id": "11-B", "category": "二、商品展示與企業數位視覺", "item": 11, "title": "商業簡報封面", "variant": "B", "label": "新增一：教育創新提案", "prompt": "請設計16:9橫式「教育創新提案」簡報封面，主題為【提案名稱】。以書頁、對話框與數位節點融合成主視覺，使用奶油白、墨綠及暖橘，畫面左側安排清楚標題，右側呈現簡潔插畫。下方放【學校或單位、提案人、日期】，整體親切且專業，適合教師研習與校務會議，文字保持易讀。", "fields": ["提案名稱", "學校或單位、提案人、日期"], "image": "assets/images/11-B.webp", "imageStatus": "complete"}, {"id": "11-C", "category": "二、商品展示與企業數位視覺", "item": 11, "title": "商業簡報封面", "variant": "C", "label": "新增二：永續策略簡報", "prompt": "請製作16:9橫式企業永續策略簡報封面，主題為【策略名稱】。以城市建築、自然植栽與循環線條構成右側主視覺，左側保留大標及副標，採深綠、灰白與少量金色。使用寫實攝影結合乾淨幾何遮罩，避免密集環保圖示；底部列出【單位、日期】，呈現穩健、清楚且具有前瞻性的企業感。", "fields": ["策略名稱", "單位、日期"], "image": "assets/images/11-C.webp", "imageStatus": "complete"}, {"id": "12-A", "category": "二、商品展示與企業數位視覺", "item": 12, "title": "公司介紹圖卡", "variant": "A", "label": "優化版：理念與服務", "prompt": "請製作3:2橫式【公司名稱】介紹圖卡，內容依提供資料呈現品牌理念、三項主要服務與三項核心特色。左側放公司名稱及一句價值主張，右側用三組圖示卡呈現服務，下方以簡短關鍵詞整理特色。使用【品牌色】、白色背景與整齊網格，字級層次清楚，不虛構成立年份、客戶數或認證。", "fields": ["公司名稱", "品牌色"], "image": "assets/images/12-A.webp", "imageStatus": "complete"}, {"id": "12-B", "category": "二、商品展示與企業數位視覺", "item": 12, "title": "公司介紹圖卡", "variant": "B", "label": "新增一：品牌故事時間軸", "prompt": "請設計16:9橫式公司故事圖卡，依【已確認的公司發展資料】呈現四個重要里程碑。上方放品牌名稱與核心使命，中間用由左至右的時間軸搭配小型場景插畫，下方整理目前服務方向。採深藍、淺灰及品牌亮色，年份、事件與圖示一一對應，保留留白，缺少的日期不自行補上。", "fields": ["已確認的公司發展資料"], "image": "assets/images/12-B.webp", "imageStatus": "complete"}, {"id": "12-C", "category": "二、商品展示與企業數位視覺", "item": 12, "title": "公司介紹圖卡", "variant": "C", "label": "新增二：服務生態系", "prompt": "請製作1:1公司服務介紹視覺，以【核心服務】為中央圓形節點，周圍安排【四項相關服務】並用清楚連線表示關係。每項搭配一致線條圖示與一句短說明，採白底、品牌主色及柔和輔色。資訊順序清楚，避免連線交錯，中央品牌識別明顯；文字只使用提供的服務內容，不加入不存在的承諾。", "fields": ["核心服務", "四項相關服務"], "image": "assets/images/12-C.webp", "imageStatus": "complete"}, {"id": "13-A", "category": "二、商品展示與企業數位視覺", "item": 13, "title": "App Icon設計", "variant": "A", "label": "優化版：寵物養成App", "prompt": "請設計1:1寵物養成App圖示，以圓潤寵物臉結合嫩芽形成單一核心符號，象徵陪伴與成長。使用柔和綠色及白色，簡約幾何造型、輕微立體層次，主體居中且邊界清楚，避免文字、細小圖案與把多種功能塞入圖示。另以文字說明設計概念及可延伸的餵食、紀錄、成就圖示方向。", "fields": [], "image": "assets/images/13-A.webp", "imageStatus": "complete"}, {"id": "13-B", "category": "二、商品展示與企業數位視覺", "item": 13, "title": "App Icon設計", "variant": "B", "label": "新增一：閱讀紀錄App", "prompt": "請設計1:1閱讀紀錄App圖示，將翻開的書與小星星整合成簡單、可辨識的符號，使用暖橘、奶油白及深棕。採平面幾何搭配柔和陰影，書本輪廓清楚，中心構圖，四周留出安全空間。不要加入書名、字母或細碎裝飾；另以文字說明如何傳達閱讀累積與成就感。", "fields": [], "image": "assets/images/13-B.webp", "imageStatus": "complete"}, {"id": "13-C", "category": "二、商品展示與企業數位視覺", "item": 13, "title": "App Icon設計", "variant": "C", "label": "新增二：專注時間App", "prompt": "請設計1:1專注時間App圖示，以沙漏與葉片融合成一個簡潔符號，使用霧藍、白色及少量薄荷綠。造型現代、圓潤，具清楚正負空間，縮小仍能辨識，不使用多個儀表板或文字。呈現淺色背景與深色背景兩種應用示意，設計概念另以文字解釋，主圖維持乾淨。", "fields": [], "image": "assets/images/13-C.webp", "imageStatus": "complete"}, {"id": "14-A", "category": "二、商品展示與企業數位視覺", "item": 14, "title": "部落格文章首圖", "variant": "A", "label": "優化版：生活與工作效率", "prompt": "請設計16:9橫式部落格首圖，主題為【生活風格與工作效率文章標題】。以整潔木桌、筆電、筆記本、咖啡與植物形成主場景，採柔和日光、奶油白及鼠尾草綠。主體放在右側，左側保留約40%標題區，整體具有獨立內容網站的清爽閱讀感；避免密集小字、誇張科技光效與品牌介面。", "fields": ["生活風格與工作效率文章標題"], "image": "assets/images/14-A.webp", "imageStatus": "complete"}, {"id": "14-B", "category": "二、商品展示與企業數位視覺", "item": 14, "title": "部落格文章首圖", "variant": "B", "label": "新增一：AI教育文章", "prompt": "請製作16:9橫式文章首圖，主題為【AI教育文章名稱】。以教師與學生共同整理知識卡片的原創插畫為中心，加入書本、對話框與簡化資料節點。使用明亮藍、暖黃與白色，保留左上標題空間，人物互動自然，焦點在學習與思考，避免把AI畫成取代教師的巨大機器或加入無關程式碼。", "fields": ["AI教育文章名稱"], "image": "assets/images/14-B.webp", "imageStatus": "complete"}, {"id": "14-C", "category": "二、商品展示與企業數位視覺", "item": 14, "title": "部落格文章首圖", "variant": "C", "label": "新增二：深度閱讀文章", "prompt": "請設計3:2橫式深度閱讀部落格首圖，主題為【文章標題】。以窗邊翻開的書、鉛筆、便條紙與玻璃水杯形成安靜場景，使用米白、深棕及低彩度藍，淺景深攝影，紙頁質感細緻。畫面下方展示閱讀物件，上方保留乾淨文字區，不生成書頁上的長段落，營造專注與思辨氛圍。", "fields": ["文章標題"], "image": "assets/images/14-C.webp", "imageStatus": "complete"}, {"id": "15-A", "category": "三、知識整理與工作資訊設計", "item": 15, "title": "教學資訊圖", "variant": "A", "label": "優化版：AI工具使用方法", "prompt": "請依【AI工具操作內容】設計3:2橫式教學資訊圖，對象為初學者。依序呈現設定目標、輸入資料、撰寫提示、檢查結果與修訂五個步驟，每步配一個一致風格的圖示、一句操作說明及清楚編號。使用白色、深藍與青綠，以箭頭建立單一路徑，底部放一個實際示例；步驟依提供資料，不虛構按鈕名稱或操作介面。", "fields": ["AI工具操作內容"], "image": "assets/images/15-A.webp", "imageStatus": "complete"}, {"id": "15-B", "category": "三、知識整理與工作資訊設計", "item": 15, "title": "教學資訊圖", "variant": "B", "label": "新增一：高中概念教學", "prompt": "請依【教材】製作A4直式概念資訊圖，主題為【單元名稱】，適合高中生閱讀。上方提出核心問題，中段用三個概念區呈現定義、生活例子與常見誤解，下方放一題思考問題。使用明亮藍、暖橘及米白，搭配原創情境插畫；概念之間用有標示的箭頭連接，文字精簡但不改變教材意思。", "fields": ["教材", "單元名稱"], "image": "assets/images/15-B.webp", "imageStatus": "complete"}, {"id": "15-C", "category": "三、知識整理與工作資訊設計", "item": 15, "title": "教學資訊圖", "variant": "C", "label": "新增二：工具操作速查卡", "prompt": "請製作4:5直式【工具名稱】操作速查卡，依【已確認操作步驟】安排「開始前、操作中、完成後」三區。每區最多三個重點，搭配簡潔圖示、編號及注意事項小框，採奶油白、墨綠及橘色。保留大字與留白，讓手機閱讀清楚；若有介面截圖，依提供圖片呈現，不自行生成不存在的功能。", "fields": ["工具名稱", "已確認操作步驟"], "image": "assets/images/15-C.webp", "imageStatus": "complete"}, {"id": "16-A", "category": "三、知識整理與工作資訊設計", "item": 16, "title": "產品比較表", "variant": "A", "label": "優化版：方案比較", "prompt": "請依【方案資料】設計16:9橫式產品比較表，欄位為【三種方案】，列項為價格、主要功能、限制與適合對象。使用白底、深藍標題與淡灰交錯列色，提供的【推薦方案】可用柔和品牌色凸顯；勾選、數值與文字一一對應，欄寬足夠，不縮成難讀小字。缺少資料標為「未提供」，不補造價格或功能。", "fields": ["方案資料", "三種方案", "推薦方案"], "image": "assets/images/16-A.webp", "imageStatus": "complete"}, {"id": "16-B", "category": "三、知識整理與工作資訊設計", "item": 16, "title": "產品比較表", "variant": "B", "label": "新增一：工具選擇矩陣", "prompt": "請依【工具比較資料】製作3:2橫式選擇矩陣，比較【工具A、B、C】的學習門檻、使用情境、輸出形式與費用。採淺色背景、清楚分欄及一致圖示，每列用簡短文字說明，不以星等取代未提供的證據。底部加入依資料整理的「適合誰」區，使用霧藍與暖黃點綴，閱讀順序清楚。", "fields": ["工具比較資料", "工具A、B、C"], "image": "assets/images/16-B.webp", "imageStatus": "complete"}, {"id": "16-C", "category": "三、知識整理與工作資訊設計", "item": 16, "title": "產品比較表", "variant": "C", "label": "新增二：新舊產品對照", "prompt": "請依【舊款與新款資料】設計4:5直式對照圖，上方展示兩款商品參考圖，下方比較外觀、功能、尺寸與使用情境。使用左右兩欄與固定對齊的項目標籤，新增功能以單一亮色標記，其他資訊保持中性色。保留商品真實比例與包裝，不添加未確認的改良項目、測試結果或推薦結論。", "fields": ["舊款與新款資料"], "image": "assets/images/16-C.webp", "imageStatus": "complete"}, {"id": "17-A", "category": "三、知識整理與工作資訊設計", "item": 17, "title": "Q&A問答圖卡", "variant": "A", "label": "優化版：客服FAQ", "prompt": "請依【常見問題與回答】製作4:5直式FAQ圖卡，一張呈現三組問答。使用白底、品牌色標籤與圓角區塊，問題以較大粗體呈現，回答以清楚短段落呈現，搭配對話框圖示。頁首放【品牌名稱】與「你可能想知道」，頁尾保留客服聯絡區，所有政策、日期與條件依提供內容，不擅自補上承諾。", "fields": ["常見問題與回答", "品牌名稱"], "image": "assets/images/17-A.webp", "imageStatus": "complete"}, {"id": "17-B", "category": "三、知識整理與工作資訊設計", "item": 17, "title": "Q&A問答圖卡", "variant": "B", "label": "新增一：單題深入解答", "prompt": "請設計1:1單題問答卡，主題為【問題】，答案為【提供的回答】。上半部用醒目的問題標題與原創提問人物，下半部用三個重點整理答案；使用奶油白、深綠與暖黃，閱讀順序由上至下。重點詞適度突出，保留充足留白，不加入未提供的原因或結論，適合逐張發布的知識系列。", "fields": ["問題", "提供的回答"], "image": "assets/images/17-B.webp", "imageStatus": "complete"}, {"id": "17-C", "category": "三、知識整理與工作資訊設計", "item": 17, "title": "Q&A問答圖卡", "variant": "C", "label": "新增二：學生概念釐清", "prompt": "請依【教材問答】製作A4直式「同學常問的問題」圖卡，安排四組問題、簡短解釋與生活例子。採校園青春插畫、霧藍與橘色，題目清楚編號，每組用一致區塊呈現。下方保留「還想問什麼？」書寫區，文字適合高中生理解，避免把解釋簡化成不正確口訣或加入未經查核的事實。", "fields": ["教材問答"], "image": "assets/images/17-C.webp", "imageStatus": "complete"}, {"id": "18-A", "category": "三、知識整理與工作資訊設計", "item": 18, "title": "操作流程圖解", "variant": "A", "label": "優化版：帳號註冊流程", "prompt": "請依【網站實際註冊流程】設計3:2橫式操作圖解，依序呈現開啟頁面、輸入資料、驗證信箱、設定密碼及完成註冊；若實際流程不同，依資料調整。每步搭配一致線條圖示、清楚編號與短句，使用白、深藍及青綠。箭頭方向一致，下方放【已知注意事項】，不呈現真實密碼或虛構介面。", "fields": ["網站實際註冊流程", "已知注意事項"], "image": "assets/images/18-A.webp", "imageStatus": "complete"}, {"id": "18-B", "category": "三、知識整理與工作資訊設計", "item": 18, "title": "操作流程圖解", "variant": "B", "label": "新增一：學生作業繳交", "prompt": "請依【作業繳交規範】製作A4直式流程圖，呈現確認題目、完成檔案、檢查命名、上傳作業與確認繳交。使用原創學生、資料夾與勾選圖示，採明亮藍、暖黃及白色；重要期限用獨立區塊標示。每步附一句具體提醒，路徑清楚，不加入未提供的平台操作或截止日期。", "fields": ["作業繳交規範"], "image": "assets/images/18-B.webp", "imageStatus": "complete"}, {"id": "18-C", "category": "三、知識整理與工作資訊設計", "item": 18, "title": "操作流程圖解", "variant": "C", "label": "新增二：錯誤排除分支", "prompt": "請依【故障排除資料】製作16:9橫式流程圖，主題為【問題名稱】。用圓角框表示操作、菱形表示判斷，箭頭標示「是／否」，清楚呈現問題確認、兩種處理分支與完成條件。採深灰、藍色與橘色，避免交叉連線，重要訊息保持大字；分支與解決方法嚴格依資料，不自行保證問題必然解決。", "fields": ["故障排除資料", "問題名稱"], "image": "assets/images/18-C.webp", "imageStatus": "complete"}, {"id": "19-A", "category": "三、知識整理與工作資訊設計", "item": 19, "title": "數據資訊圖", "variant": "A", "label": "優化版：市場調查", "prompt": "請依【市場調查數據】製作16:9橫式資訊圖，包含標題、三項主要發現與一張符合資料型態的圖表。類別比較用長條圖，時間變化用折線圖；標示單位、調查期間、樣本數與來源，使用白底、深藍及單一亮色突出重點。圖形比例必須符合數值，無法精確呈現時保留圖表區供後製，不編造數據。", "fields": ["市場調查數據"], "image": "assets/images/19-A.webp", "imageStatus": "complete"}, {"id": "19-B", "category": "三、知識整理與工作資訊設計", "item": 19, "title": "數據資訊圖", "variant": "B", "label": "新增一：問卷結果摘要", "prompt": "請依【問卷統計表】設計A4直式結果摘要，呈現受訪者概況、三項核心結果與待討論問題。使用水平長條圖及簡短註解，標示題目、百分比、樣本數及是否為複選題，採墨綠、米白及暖橘。將資料事實與提供的解讀分區，避免圖示數量與比例不符，不自行推論因果關係。", "fields": ["問卷統計表"], "image": "assets/images/19-B.webp", "imageStatus": "complete"}, {"id": "19-C", "category": "三、知識整理與工作資訊設計", "item": 19, "title": "數據資訊圖", "variant": "C", "label": "新增二：年度成果看板", "prompt": "請依【年度成果資料】製作3:2橫式成果看板，上方放年度與主題，中段三張數字卡，下方以折線或長條圖呈現【已提供趨勢】。採企業深藍、白色及青綠，數字、單位與期間清楚對齊。僅在資料包含比較基準時呈現成長率，避免截斷座標誇大變化，來源與註解置於底部且可閱讀。", "fields": ["年度成果資料", "已提供趨勢"], "image": "assets/images/19-C.webp", "imageStatus": "complete"}, {"id": "20-A", "category": "三、知識整理與工作資訊設計", "item": 20, "title": "工作Checklist清單", "variant": "A", "label": "優化版：活動籌備", "prompt": "請設計A4直式活動籌備Checklist，依【活動內容】分為事前規劃、場地設備、人員聯繫、當日執行與活動後整理。每區安排勾選框、簡短任務、負責人及完成日期空欄，使用白底、深藍與柔和青綠，清楚區分區標與任務。預留手寫空間，裝飾圖示少量即可，適合列印並實際勾選。", "fields": ["活動內容"], "image": "assets/images/20-A.webp", "imageStatus": "complete"}, {"id": "20-B", "category": "三、知識整理與工作資訊設計", "item": 20, "title": "工作Checklist清單", "variant": "B", "label": "新增一：文章發布檢核", "prompt": "請製作4:5直式「文章發布前檢核」圖卡，項目包含標題、內容邏輯、來源、圖片授權、文字校對、連結及手機版閱讀。每項左側放空白勾選框，右側放短句提醒，採奶油白、深棕及橘色。上方安排鉛筆與文件插畫，下方留一個備註區，版面整齊且大字清楚，不讓插畫占用勾選空間。", "fields": [], "image": "assets/images/20-B.webp", "imageStatus": "complete"}, {"id": "20-C", "category": "三、知識整理與工作資訊設計", "item": 20, "title": "工作Checklist清單", "variant": "C", "label": "新增二：課堂設備確認", "prompt": "請設計A4直式教師課前設備檢核表，依【教室設備清單】整理投影、音訊、網路、教材檔案、學生裝置與備援方式。分為「前一天」與「上課前」兩區，附勾選框、異常備註及處理欄。使用明亮藍與白色，少量線條圖示，保持足夠列高，適合列印，不加入未提供的設備型號。", "fields": ["教室設備清單"], "image": "assets/images/20-C.webp", "imageStatus": "complete"}, {"id": "21-A", "category": "三、知識整理與工作資訊設計", "item": 21, "title": "讀書筆記風", "variant": "A", "label": "優化版：主題學習筆記", "prompt": "請將【圖片或主題資料】整理成A4直式讀書筆記風資訊頁，保留原內容的核心概念與關係。使用手寫感標題、重點底線、細框線、小箭頭與便條紙區，分為主題、三項重點、例子及反思。採奶油紙色、墨藍與柔和黃，筆記感自然但正文清楚，圖示輔助理解，不添加資料未提及的事實。", "fields": ["圖片或主題資料"], "image": "assets/images/21-A.webp", "imageStatus": "complete"}, {"id": "21-B", "category": "三、知識整理與工作資訊設計", "item": 21, "title": "讀書筆記風", "variant": "B", "label": "新增一：康乃爾筆記", "prompt": "請依【學習內容】設計A4直式康乃爾筆記視覺，頁首放主題與日期，左側約三分之一為關鍵詞及提問區，右側為筆記區，底部為摘要區。使用米白紙色、深灰文字與少量藍色標記，加入淡淡紙紋與簡潔手繪符號。資訊依資料分類，留出補充書寫空間，不把正文排成過度裝飾的碎片。", "fields": ["學習內容"], "image": "assets/images/21-B.webp", "imageStatus": "complete"}, {"id": "21-C", "category": "三、知識整理與工作資訊設計", "item": 21, "title": "讀書筆記風", "variant": "C", "label": "新增二：閱讀反思雙頁", "prompt": "請依【閱讀資料】設計3:2橫式雙頁閱讀筆記，左頁整理「作者說了什麼」，右頁整理「我的理解與疑問」。使用暖白、棕色及淡綠便條紙，加入書籤、鉛筆線及少量手繪圖示；明確區分原文摘要與使用者提供的心得。右頁保留三個反思空欄，版面像打開的筆記本，但文字不因透視而難以閱讀。", "fields": ["閱讀資料"], "image": "assets/images/21-C.webp", "imageStatus": "complete"}, {"id": "22-A", "category": "四、生活規劃與日常資訊", "item": 22, "title": "菜單設計", "variant": "A", "label": "優化版：文青咖啡館", "prompt": "請依【店名、品項與價格】設計A4直式咖啡館菜單，分為咖啡、其他飲品與甜點。使用奶油色背景、深棕正文、手寫感標題，搭配少量咖啡杯、甜點與植物插畫；品名靠左、價格靠右整齊對齊。保留清楚列距與留白，呈現獨立咖啡店的溫暖感；不自行新增價格、容量或成分。", "fields": ["店名、品項與價格"], "image": "assets/images/22-A.webp", "imageStatus": "complete"}, {"id": "22-B", "category": "四、生活規劃與日常資訊", "item": 22, "title": "菜單設計", "variant": "B", "label": "新增一：日式定食菜單", "prompt": "請依【定食品項及售價】製作A4直式日式餐館菜單，使用米白、靛藍與暖木色。上方放店名，中段以三組主餐插畫搭配品名、售價與提供的配菜說明，下方整理加點品項。採清楚橫排繁體中文，搭配細緻墨線與淡水彩，食物樣貌符合品項，裝飾不遮住價格或過敏原資訊。", "fields": ["定食品項及售價"], "image": "assets/images/22-B.webp", "imageStatus": "complete"}, {"id": "22-C", "category": "四、生活規劃與日常資訊", "item": 22, "title": "菜單設計", "variant": "C", "label": "新增二：外帶甜點價目表", "prompt": "請設計4:5直式外帶甜點價目表，依【甜點資料】展示六個品項。使用粉杏、奶油白及可可棕，採兩欄三列卡片，每卡包含甜點插畫、名稱、價格與一句短說明。頁首放【品牌名稱】，頁尾保留【訂購方式】，品項順序一致、字級清楚，不生成假的QR碼或未提供的促銷內容。", "fields": ["甜點資料", "品牌名稱", "訂購方式"], "image": "assets/images/22-C.webp", "imageStatus": "complete"}, {"id": "23-A", "category": "四、生活規劃與日常資訊", "item": 23, "title": "季節月曆", "variant": "A", "label": "優化版：春季月曆", "prompt": "請依【年份、月份、已校對日期表】設計A4直式春季月曆，星期排列為【週日開始或週一開始】。上方以櫻花枝、柔和天空及小鳥插畫呈現春天，中下方使用整齊七欄日期格。採粉色、米白及淺綠，日期大且清楚，保留每格書寫空間；節日僅標示提供資料，不自行推算或新增。", "fields": ["年份、月份、已校對日期表", "週日開始或週一開始"], "image": "assets/images/23-A.webp", "imageStatus": "complete"}, {"id": "23-B", "category": "四、生活規劃與日常資訊", "item": 23, "title": "季節月曆", "variant": "B", "label": "新增一：秋季閱讀月曆", "prompt": "請製作A4直式秋季閱讀月曆，依【已校對年月日期】排出完整七欄日曆。以楓葉、書堆與暖茶作邊角插畫，使用米黃、磚紅及棕色；每個日期格保留閱讀紀錄空間，底部放「本月想讀」三列空欄。星期與日期逐格對應，圖案集中在外圍，避免壓縮實際書寫區。", "fields": ["已校對年月日期"], "image": "assets/images/23-B.webp", "imageStatus": "complete"}, {"id": "23-C", "category": "四、生活規劃與日常資訊", "item": 23, "title": "季節月曆", "variant": "C", "label": "新增二：年度季節總覽", "prompt": "請依【年份及12個月日期資料】設計3:2橫式年度月曆，採四欄三列排列十二個月份，每月七欄且結構一致。四季用淡綠、淡黃、暖橘及霧藍區分，加入少量對應花草圖示。主標題位於上方，數字清楚，不添加未提供的節日；日期太密時優先放大文字並減少裝飾，不省略日期。", "fields": ["年份及12個月日期資料"], "image": "assets/images/23-C.webp", "imageStatus": "complete"}, {"id": "24-A", "category": "四、生活規劃與日常資訊", "item": 24, "title": "旅遊行程規劃表", "variant": "A", "label": "優化版：釜山四天三夜", "prompt": "請分三階段處理「釜山4天3夜自由行」：先依【日期、住宿、預算、偏好】查核交通、營業資訊並安排區域集中的行程；再寫成有畫面感的旅遊雜誌攻略；最後依確認內容製作2:3直式拼貼海報。以每日卡片呈現景點、移動方式與亮點，加入海岸、街景及車票元素；若無法查詢最新資訊，先標示待查項目，不編造班次與票價。", "fields": ["日期、住宿、預算、偏好"], "image": "assets/images/24-A.webp", "imageStatus": "complete"}, {"id": "24-B", "category": "四、生活規劃與日常資訊", "item": 24, "title": "旅遊行程規劃表", "variant": "B", "label": "新增一：京都文化散步", "prompt": "請依【已確認的京都3天2夜行程】設計A4直式旅遊攻略海報，按日期與區域安排散步路線、交通方式、休息點及用餐備註。使用和紙米白、抹茶綠與朱紅，搭配寺院、街巷及茶點插畫。每一天有清楚色標與順序，路線僅依提供資料繪製簡圖，標註「示意」，不把藝術插畫當精確導航地圖。", "fields": ["已確認的京都3天2夜行程"], "image": "assets/images/24-B.webp", "imageStatus": "complete"}, {"id": "24-C", "category": "四、生活規劃與日常資訊", "item": 24, "title": "旅遊行程規劃表", "variant": "C", "label": "新增二：台灣週末輕旅行", "prompt": "請依【目的地、日期、交通及行程】製作3:2橫式兩天一夜輕旅行規劃圖。左側放區域示意及景點插畫，右側分Day 1與Day 2呈現上午、下午、晚上的安排，下方放雨天備案及攜帶清單。使用天空藍、奶油白與暖橘，交通時間及費用依已確認資料，保留適當休息時間，不任意新增店家。", "fields": ["目的地、日期、交通及行程"], "image": "assets/images/24-C.webp", "imageStatus": "complete"}, {"id": "25-A", "category": "四、生活規劃與日常資訊", "item": 25, "title": "編織小人氣象圖", "variant": "A", "label": "優化版：毛線城市氣象", "prompt": "請依【城市、日期、天氣、最低最高溫、降雨機率】製作3:2橫式氣象圖，中央為清楚可讀的編織風資訊牌，周圍以毛線與鉤針材質打造【城市代表建物】、道路與小人物。使用柔和奶油色及天空藍，毛線纖維細緻，天氣符號與資料一致；資訊牌保持正面，標示資料時間，不自行產生即時天氣數值。", "fields": ["城市、日期、天氣、最低最高溫、降雨機率", "城市代表建物"], "image": "assets/images/25-A.webp", "imageStatus": "complete"}, {"id": "25-B", "category": "四、生活規劃與日常資訊", "item": 25, "title": "編織小人氣象圖", "variant": "B", "label": "新增一：雨天小鎮", "prompt": "請依【已確認的氣象資料】設計1:1毛線小鎮天氣圖，畫面有撐傘小人、針織雨雲、濕潤街道及暖光咖啡店。中央牌面清楚列出【地點、日期、溫度、降雨機率】，使用霧藍、灰白與暖黃。呈現可愛立體纖維質感，雨滴不遮住文字，所有數字保持資料原值，避免把裝飾性雨量當成統計比例。", "fields": ["已確認的氣象資料", "地點、日期、溫度、降雨機率"], "image": "assets/images/25-B.webp", "imageStatus": "complete"}, {"id": "25-C", "category": "四、生活規劃與日常資訊", "item": 25, "title": "編織小人氣象圖", "variant": "C", "label": "新增二：一週天氣看板", "prompt": "請依【七天氣象表】製作16:9橫式編織風一週天氣看板，七張日期卡並排，每張顯示星期、天氣符號、溫度範圍及降雨機率。背景是簡潔毛線城市，小人物只放在底部；使用米白、淺綠及柔和藍，卡片文字大且一致，日期逐一核對，資料不足的欄位保留空白，不補造預報。", "fields": ["七天氣象表"], "image": "assets/images/25-C.webp", "imageStatus": "complete"}, {"id": "26-A", "category": "四、生活規劃與日常資訊", "item": 26, "title": "時間管理規劃圖", "variant": "A", "label": "優化版：24小時分配", "prompt": "請依【一天時間分配資料】設計3:2橫式24小時規劃圖，以0至24時的連續時間軸呈現工作、學習、運動、娛樂與休息。每類用不同色塊與文字標籤，標示起訖時間，區段長度依時數比例；下方整理各類總時數。採白底、低彩度配色與清楚圖例，先確認合計24小時且不重疊，再依資料繪製。", "fields": ["一天時間分配資料"], "image": "assets/images/26-A.webp", "imageStatus": "complete"}, {"id": "26-B", "category": "四、生活規劃與日常資訊", "item": 26, "title": "時間管理規劃圖", "variant": "B", "label": "新增一：學生放學規劃", "prompt": "請依【放學後時段安排】製作4:5直式學生時間規劃卡，從【開始時間】至【就寢時間】分段呈現交通、晚餐、讀書、休息與準備隔日用品。採校園插畫、霧藍及暖黃，以垂直時間軸配清楚時刻，右側留實際執行紀錄空欄。不得安排重疊時段，底部保留「今天最重要的一件事」區。", "fields": ["放學後時段安排", "開始時間", "就寢時間"], "image": "assets/images/26-B.webp", "imageStatus": "complete"}, {"id": "26-C", "category": "四、生活規劃與日常資訊", "item": 26, "title": "時間管理規劃圖", "variant": "C", "label": "新增二：一週時間區塊", "prompt": "請依【一週行程】設計A4橫式時間區塊表，七欄為星期，列為【指定時間範圍】。用不同色塊區分固定工作、深度專注、彈性任務與休息，搭配文字圖例，保留可新增的空白區。採白、深灰及淡藍配色，避免裝飾過量；時間及事件依資料逐格對應，不自行填滿所有空檔。", "fields": ["一週行程", "指定時間範圍"], "image": "assets/images/26-C.webp", "imageStatus": "complete"}, {"id": "27-A", "category": "四、生活規劃與日常資訊", "item": 27, "title": "美食插圖", "variant": "A", "label": "優化版：草莓鬆餅", "prompt": "請繪製4:5直式草莓鬆餅插畫，厚鬆餅疊放於白色陶瓷盤，搭配新鮮草莓、少量鮮奶油與自然流動的蜂蜜。採細緻水彩與彩鉛質感，呈現鬆餅孔洞、草莓籽及奶油柔軟感，背景為暖米色餐桌。光線由左上照入，擺盤乾淨，右上留文案位置，整體適合餐廳菜單主視覺。", "fields": [], "image": "assets/images/27-A.webp", "imageStatus": "complete"}, {"id": "27-B", "category": "四、生活規劃與日常資訊", "item": 27, "title": "美食插圖", "variant": "B", "label": "新增一：台灣早餐插畫", "prompt": "請繪製3:2橫式台灣早餐插畫，主體為【蛋餅、飯糰及豆漿等指定品項】，排列於溫暖木桌，以三分之四視角呈現食物層次與真實份量。使用手繪水彩、暖黃與奶油白，保留煎香表面、米粒及杯身細節，背景簡單；各品項旁預留名稱位置，不添加不存在的品牌標誌。", "fields": ["蛋餅、飯糰及豆漿等指定品項"], "image": "assets/images/27-B.webp", "imageStatus": "complete"}, {"id": "27-C", "category": "四、生活規劃與日常資訊", "item": 27, "title": "美食插圖", "variant": "C", "label": "新增二：季節甜點拼盤", "prompt": "請繪製1:1季節甜點插畫，展示【三種指定甜點】，採俯視構圖，使用陶瓷盤、自然果實與少量布巾形成平衡。配色依【季節】選擇，細緻呈現蛋糕切面、糖霜與果皮，陰影柔和，盤子不互相遮擋。畫面外圍保留留白供菜單排版，風格精緻溫暖，不加入多餘餐具。", "fields": ["三種指定甜點", "季節"], "image": "assets/images/27-C.webp", "imageStatus": "complete"}, {"id": "28-A", "category": "四、生活規劃與日常資訊", "item": 28, "title": "一週習慣追蹤表", "variant": "A", "label": "優化版：六項生活習慣", "prompt": "請設計A4直式一週習慣追蹤表，七欄為星期一至星期日，六列為運動、閱讀、喝水、冥想、早睡與學習。每格放清楚空白勾選框，左側搭配簡潔小圖示，上方保留【週次或日期】，下方留反思區。使用奶油白、淺綠及淡藍，字體大而清楚，圖示不占勾選區，所有格子保持空白供使用者紀錄。", "fields": ["週次或日期"], "image": "assets/images/28-A.webp", "imageStatus": "complete"}, {"id": "28-B", "category": "四、生活規劃與日常資訊", "item": 28, "title": "一週習慣追蹤表", "variant": "B", "label": "新增一：自主學習追蹤", "prompt": "請製作A4橫式學生自主學習追蹤表，依【本週目標】安排資料閱讀、實作、紀錄、問題整理及成果整理五列，七欄為日期。使用明亮藍、白色及暖橘，附「完成／待調整」紀錄區及週末反思空欄；版面清楚、適合列印，保留手寫空間，不預先勾選，也不把每天都設定為必須完成全部項目。", "fields": ["本週目標"], "image": "assets/images/28-B.webp", "imageStatus": "complete"}, {"id": "28-C", "category": "四、生活規劃與日常資訊", "item": 28, "title": "一週習慣追蹤表", "variant": "C", "label": "新增二：小步驟養成卡", "prompt": "請設計4:5直式「每天一小步」習慣卡，依【三項微習慣】安排一週追蹤，每項包含具體行動、觸發時機與七個空白圈。使用淡杏、米白及墨綠，搭配發芽植物插畫，下方保留「最容易做到的條件」與「下週調整」欄。追蹤單位清楚，不加入未提供的健康數值或達成標準。", "fields": ["三項微習慣"], "image": "assets/images/28-C.webp", "imageStatus": "complete"}, {"id": "29-A", "category": "四、生活規劃與日常資訊", "item": 29, "title": "電影觀後感筆記", "variant": "A", "label": "優化版：電影分析卡", "prompt": "請依【電影名稱與觀後資料】設計A4直式觀後感卡，包含評分、角色分析、關鍵場景、提供的台詞與心得。採電影票、底片框及放映光束元素，使用奶油白、黑色與酒紅，主標清楚，各區保留手寫空間。台詞僅使用提供內容並註明角色，若無資料則留空，不自行杜撰片中對話。", "fields": ["電影名稱與觀後資料"], "image": "assets/images/29-A.webp", "imageStatus": "complete"}, {"id": "29-B", "category": "四、生活規劃與日常資訊", "item": 29, "title": "電影觀後感筆記", "variant": "B", "label": "新增一：故事結構筆記", "prompt": "請設計3:2橫式電影故事分析頁，依【觀影資料】整理開端、衝突、轉折與結局四個區塊，下方加上主題與疑問。使用深藍、暖白及少量金色，以簡化分鏡插畫建立時間順序，區塊標題大而清楚。劇情文字由提供資料整理，明確保留填寫區，不生成未出現的角色或場景。", "fields": ["觀影資料"], "image": "assets/images/29-B.webp", "imageStatus": "complete"}, {"id": "29-C", "category": "四、生活規劃與日常資訊", "item": 29, "title": "電影觀後感筆記", "variant": "C", "label": "新增二：情緒觀影日記", "prompt": "請製作4:5直式文青觀影日記卡，內容包括【片名、觀影日期】、「印象最深的畫面」「讓我想到的生活經驗」「想問導演的問題」。以手繪電影院座椅、票根及小型星星評分框裝飾，採奶茶色與霧藍。文字區充足，心情圖示可愛但不代替內容，所有心得欄保留空白或使用提供文字。", "fields": ["片名、觀影日期"], "image": "assets/images/29-C.webp", "imageStatus": "complete"}, {"id": "30-A", "category": "五、故事創作與出版封面", "item": 30, "title": "四格漫畫", "variant": "A", "label": "優化版：開會崩潰日常", "prompt": "請製作2:3直式四格漫畫，四格由上至下，主題為「每天開會的崩潰日常」。第一格期待準時下班，第二格臨時會議開始，第三格討論是否需要再開會，第四格主角看到下一場會議通知露出無奈表情。使用同一位可愛上班族，日系漫畫感、清楚線條及柔和配色；每格最多一句短對白，讓表情與動作形成幽默節奏。", "fields": [], "image": "assets/images/30-A.webp", "imageStatus": "complete"}, {"id": "30-B", "category": "五、故事創作與出版封面", "item": 30, "title": "四格漫畫", "variant": "B", "label": "新增一：學生與作業", "prompt": "請設計2:2排列的四格漫畫，1:1整體比例，主題為「想先休息五分鐘」。依左上、右上、左下、右下順序呈現學生打開作業、滑一下手機、窗外天色改變、終於放下手機發現已到晚上。角色外觀一致，校園青春插畫、明亮配色，對白簡短清楚，最後一格用表情製造笑點，不以文字塞滿畫面。", "fields": [], "image": "assets/images/30-B.webp", "imageStatus": "complete"}, {"id": "30-C", "category": "五、故事創作與出版封面", "item": 30, "title": "四格漫畫", "variant": "C", "label": "新增二：AI提示詞日常", "prompt": "請製作2:3直式四格漫畫，主題為「提示詞越寫越清楚」。第一格人物只輸入「幫我做」，第二格收到不合需求的結果，第三格補上對象、用途與格式，第四格得到清楚成果並露出安心表情。使用同一原創角色與簡化對話介面，奶油白、藍色及橘色，流程易懂；不引用實際平台Logo，對白短且有輕鬆幽默感。", "fields": [], "image": "assets/images/30-C.webp", "imageStatus": "complete"}, {"id": "31-A", "category": "五、故事創作與出版封面", "item": 31, "title": "LINE貼圖角色", "variant": "A", "label": "優化版：四種情緒", "prompt": "請設計四張獨立Q版聊天貼圖，角色為【角色設定】，分別表現開心、無奈、生氣與驚訝。統一頭身比例、服裝、主色與線條粗細，表情誇張但清楚，搭配簡短文字「耶！」「好吧」「氣噗噗」「真的假的」。每張1:1比例、透明背景、四周留安全空間，輪廓完整，不把四張合成一張；成品作為貼圖設計素材。", "fields": ["角色設定"], "image": "assets/images/31-A.webp", "imageStatus": "complete"}, {"id": "31-B", "category": "五、故事創作與出版封面", "item": 31, "title": "LINE貼圖角色", "variant": "B", "label": "新增一：教師日常貼圖", "prompt": "請設計四張獨立教師角色聊天貼圖，內容為「辛苦了」「請交作業」「再想一下」「做得很好」。角色以【教師外觀設定】為參考，圓潤Q版、表情親切，搭配書本、紅筆與小星星等少量道具。採清楚粗線及柔和配色，每張透明背景、1:1，文字與角色不互相遮擋，服裝與五官保持一致。", "fields": ["教師外觀設定"], "image": "assets/images/31-B.webp", "imageStatus": "complete"}, {"id": "31-C", "category": "五、故事創作與出版封面", "item": 31, "title": "LINE貼圖角色", "variant": "C", "label": "新增二：圖書館動物貼圖", "prompt": "請設計四張獨立圖書館小貓貼圖，情境為閱讀中、找書、感謝與安靜提醒，文字分別為「我在閱讀」「找到了」「謝謝你」「小聲一點」。小貓戴圓框眼鏡，採奶油黃、墨綠及深棕，線條簡潔、動作清楚；每張1:1透明背景，保留完整耳朵與尾巴，縮小仍能辨識文字與表情。", "fields": [], "image": "assets/images/31-C.webp", "imageStatus": "complete"}, {"id": "32-A", "category": "五、故事創作與出版封面", "item": 32, "title": "旅行日記插畫", "variant": "A", "label": "優化版：旅人筆記頁", "prompt": "請依【旅行地點與紀錄】製作A4直式旅行日記插畫，包含簡化路線示意、車票、沿途風景、食物與手寫感短句。採米白紙張、淡水彩、鉛筆線與紙膠帶拼貼，資訊按旅行順序排列，主要景點插畫清楚。地名與日期依提供資料，車票作紀念式示意，不生成可使用的真實票券或把示意路線畫成精確導航圖。", "fields": ["旅行地點與紀錄"], "image": "assets/images/32-A.webp", "imageStatus": "complete"}, {"id": "32-B", "category": "五、故事創作與出版封面", "item": 32, "title": "旅行日記插畫", "variant": "B", "label": "新增一：海邊小旅行", "prompt": "請設計3:2橫式雙頁旅行日記，主題為【海邊目的地】的一日散步。左頁呈現燈塔、海岸與咖啡店插畫，右頁放交通紀錄、天氣感受與三個旅途片刻，搭配貝殼、票根及淡藍紙膠帶。使用透明水彩、海藍與沙色，文字依提供紀錄，保留可續寫的空白，避免大量裝飾遮住故事順序。", "fields": ["海邊目的地"], "image": "assets/images/32-B.webp", "imageStatus": "complete"}, {"id": "32-C", "category": "五、故事創作與出版封面", "item": 32, "title": "旅行日記插畫", "variant": "C", "label": "新增二：城市文化散步", "prompt": "請依【城市散步紀錄】製作A4直式手帳插畫，將建築、書店、街角招牌及小吃轉為細緻鋼筆淡彩，配色低飽和。以編號標示四個停留點，旁邊配一段提供的觀察短句；角落加入手繪日期章與交通符號。整體像旅人的文化觀察筆記，保留真實地名，未提供的店家或故事不自行補寫。", "fields": ["城市散步紀錄"], "image": "assets/images/32-C.webp", "imageStatus": "complete"}, {"id": "33-A", "category": "五、故事創作與出版封面", "item": 33, "title": "黑膠唱片封面", "variant": "A", "label": "優化版：獨立樂團專輯", "prompt": "請設計1:1獨立樂團黑膠唱片封面，專輯名稱為【名稱】，樂團為【名稱】。以陰天城市邊緣、一位背對鏡頭的人物及遠方柔焦燈光營造情緒，採低飽和灰藍、褪色棕與底片顆粒。標題小而清楚置於留白處，保留文藝攝影氛圍與孤獨感，避免複製既有專輯畫面或加入未提供的曲目。", "fields": ["名稱"], "image": "assets/images/33-A.webp", "imageStatus": "complete"}, {"id": "33-B", "category": "五、故事創作與出版封面", "item": 33, "title": "黑膠唱片封面", "variant": "B", "label": "新增一：溫暖民謠", "prompt": "請設計1:1民謠黑膠封面，主題為【專輯概念】。描繪黃昏窗邊的木吉他、植物、手寫便條與暖光，使用焦糖棕、奶油白及橄欖綠，結合底片攝影與淡淡紙紋。專輯名稱與歌手名稱低調排列於左上，構圖安靜、有故事，畫面只保留少量物件，不放入不相關標誌或虛構發行資訊。", "fields": ["專輯概念"], "image": "assets/images/33-B.webp", "imageStatus": "complete"}, {"id": "33-C", "category": "五、故事創作與出版封面", "item": 33, "title": "黑膠唱片封面", "variant": "C", "label": "新增二：復古電子音樂", "prompt": "請設計1:1電子音樂唱片封面，主題為【專輯名稱】。以抽象霓虹幾何、夜間道路反射與細緻掃描線建立復古未來感，採深紫、青藍與桃紅，但控制光效不壓過標題。中央主體簡潔，四周留白，字體呈現清楚幾何感；文字僅使用提供的專輯與音樂人名稱，不模仿既有封面。", "fields": ["專輯名稱"], "image": "assets/images/33-C.webp", "imageStatus": "complete"}, {"id": "34-A", "category": "五、故事創作與出版封面", "item": 34, "title": "漫畫封面設計", "variant": "A", "label": "優化版：熱血冒險", "prompt": "請製作2:3直式原創冒險漫畫封面，主角【角色設定】站在壯闊山脈與雲海前，披風與衣角隨風形成動態，遠方有未知古城。採清楚漫畫線條、強烈光影與藍橘配色，低角度構圖展現勇氣；上方保留【漫畫標題】，角落放【集數】及【作者】，主角臉部不被文字遮擋，營造即將展開旅程的張力。", "fields": ["角色設定", "漫畫標題", "集數", "作者"], "image": "assets/images/34-A.webp", "imageStatus": "complete"}, {"id": "34-B", "category": "五、故事創作與出版封面", "item": 34, "title": "漫畫封面設計", "variant": "B", "label": "新增一：校園科幻冒險", "prompt": "請設計2:3直式校園科幻漫畫封面，主角群【三位角色設定】站在放學後的校園，身後出現透明數位裂縫與未知世界。採青春漫畫感、青藍與暖黃，主角位於前景，配角形成三角構圖，服裝與個性有區別。上方放【標題】，下方放【副標與集數】，場景動態明確但不擁擠，所有角色保持原創。", "fields": ["三位角色設定", "標題", "副標與集數"], "image": "assets/images/34-B.webp", "imageStatus": "complete"}, {"id": "34-C", "category": "五、故事創作與出版封面", "item": 34, "title": "漫畫封面設計", "variant": "C", "label": "新增二：奇幻解謎", "prompt": "請製作2:3直式奇幻解謎漫畫封面，主角手持發光地圖，站在充滿機關與藏書的古老圖書館。採紫藍、暖金及深棕，前景有鑰匙與書頁，中景為主角，後景為旋轉樓梯及神秘門。以清楚漫畫線條與戲劇光影呈現，預留【標題、集數、作者】位置，線索圖案少而明確，避免人物手部異常。", "fields": ["標題、集數、作者"], "image": "assets/images/34-C.webp", "imageStatus": "complete"}, {"id": "35-A", "category": "五、故事創作與出版封面", "item": 35, "title": "世界觀小說書封", "variant": "A", "label": "優化版：古城與夜空", "prompt": "請製作2:3直式原創奇幻小說書封，主題為【書名與世界觀】。巨大古城沿山崖層層延伸，夜空有清楚月光與星雲，一名神秘旅者站在前景，形成尺度對比。採深藍、墨綠與暖金，細緻數位繪畫、厚重氛圍與視覺深度；上方放【書名】，下方放【作者】，角色與建築依設定，不加入既有作品標誌。", "fields": ["書名與世界觀", "書名", "作者"], "image": "assets/images/35-A.webp", "imageStatus": "complete"}, {"id": "35-B", "category": "五、故事創作與出版封面", "item": 35, "title": "世界觀小說書封", "variant": "B", "label": "新增一：海洋群島世界", "prompt": "請設計2:3直式奇幻書封，世界觀為【海洋群島設定】。主視覺為漂浮在海霧中的島嶼城邦、古老帆船與遠方巨大生物輪廓，前景安排一位凝望航線的旅人。使用深青、霧白與銅金，畫面有遠近層次，上方天空保留【書名】空間，下方放作者；氣氛神秘而開闊，不用細節填滿所有留白。", "fields": ["海洋群島設定", "書名"], "image": "assets/images/35-B.webp", "imageStatus": "complete"}, {"id": "35-C", "category": "五、故事創作與出版封面", "item": 35, "title": "世界觀小說書封", "variant": "C", "label": "新增二：植物魔法世界", "prompt": "請製作2:3直式奇幻小說書封，主題為【植物魔法故事】。描繪被巨樹包圍的古老學院、發光種子與正在探索的主角，採森林綠、奶油金及深棕。以枝葉形成自然框景，焦點落在主角手中的光源，書名置於上方乾淨暗色區，作者置底部；材質細緻、氛圍寧靜而充滿未知，所有設計原創。", "fields": ["植物魔法故事"], "image": "assets/images/35-C.webp", "imageStatus": "complete"}, {"id": "36-A", "category": "五、故事創作與出版封面", "item": 36, "title": "復古雜誌封面", "variant": "A", "label": "優化版：90年代生活風格", "prompt": "請設計A4直式90年代生活風格雜誌封面，刊名為【刊名】。中央使用原創生活場景照片，搭配大刊頭、三條短封面標題與【期數、日期】；採奶油白、亮紅及靛藍，帶有輕微底片顆粒與復古印刷質感。排版活潑但閱讀順序清楚，主圖不被大量文字遮住，不複製現有雜誌刊頭或假條碼。", "fields": ["刊名", "期數、日期"], "image": "assets/images/36-A.webp", "imageStatus": "complete"}, {"id": "36-B", "category": "五、故事創作與出版封面", "item": 36, "title": "復古雜誌封面", "variant": "B", "label": "新增一：復古校園特刊", "prompt": "請製作A4直式校園生活雜誌封面，主題為【校園特刊名稱】。以原創學生在操場或校園走廊的自然場景為主圖，使用90年代青春配色：明亮黃、寶藍與白色。加入大標「我們的青春日常」與提供的三條內容預告，搭配幾何框及少量貼紙感元素，刊期依資料呈現，人物與文字層次清楚。", "fields": ["校園特刊名稱"], "image": "assets/images/36-B.webp", "imageStatus": "complete"}, {"id": "36-C", "category": "五、故事創作與出版封面", "item": 36, "title": "復古雜誌封面", "variant": "C", "label": "新增二：復古旅行特刊", "prompt": "請設計A4直式復古旅行雜誌封面，主題為【目的地】。主圖呈現街景、海岸或列車窗景，採褪色青綠、暖橘與米黃，帶有自然底片感。上方放【原創刊名】，側邊排列三條旅遊主題，下方放【日期與期數】；標題醒目、短句精簡，景點文字依提供資料，不添加未查核的推薦資訊。", "fields": ["目的地", "原創刊名", "日期與期數"], "image": "assets/images/36-C.webp", "imageStatus": "complete"}, {"id": "37-A", "category": "五、故事創作與出版封面", "item": 37, "title": "男性時尚雜誌封面", "variant": "A", "label": "優化版：日系都會街頭", "prompt": "請製作A4直式原創男性時尚雜誌封面，一位成年模特站在東京街頭，穿著簡約襯衫、寬鬆長褲與乾淨休閒鞋，髮型俐落、神情自然。參考日系城市生活刊物的街拍、清爽留白與細緻排版特徵，採霧藍、米白及黑色；加入【原創刊名與短標題】，不使用POPEYE的刊頭、Logo或照搬既有封面。", "fields": ["原創刊名與短標題"], "image": "assets/images/37-A.webp", "imageStatus": "complete"}, {"id": "37-B", "category": "五、故事創作與出版封面", "item": 37, "title": "男性時尚雜誌封面", "variant": "B", "label": "新增一：成熟極簡穿搭", "prompt": "請設計A4直式男性時尚封面，成年模特穿著深灰西裝外套、素色上衣與俐落長褲，在現代建築前自然站立。使用柔和陰天光、灰白與暖棕，整體沉穩簡潔，人物全身或四分之三身構圖。上方放【原創刊名】，右側安排兩條簡短穿搭主題，布料紋理自然，不使用現有品牌標誌。", "fields": ["原創刊名"], "image": "assets/images/37-B.webp", "imageStatus": "complete"}, {"id": "37-C", "category": "五、故事創作與出版封面", "item": 37, "title": "男性時尚雜誌封面", "variant": "C", "label": "新增二：休閒戶外機能", "prompt": "請製作A4直式男性休閒時尚封面，成年模特穿著橄欖綠輕外套、米色長褲與機能鞋，在城市公園步行。採自然抓拍、柔和日光與低彩度綠棕配色，動作放鬆，衣服剪裁與材質清楚。預留【原創刊名】及兩條內容標題，版面有日系生活雜誌感但保持獨立設計，不複製特定刊物版式。", "fields": ["原創刊名"], "image": "assets/images/37-C.webp", "imageStatus": "complete"}, {"id": "38-A", "category": "六、立體角色與微縮場景", "item": 38, "title": "黏土Q版角色", "variant": "A", "label": "優化版：黏土角色走出手機", "prompt": "請製作4:5直式黏土Q版角色圖，主角【角色設定】從巨大手機螢幕中向前跑出，身體約兩頭身，表情活潑。手機內為簡潔主題場景，外部為乾淨奶油色地面；強調霧面黏土、手工微紋、圓潤邊緣與柔和接觸陰影。採三分之四視角，一腳留在畫面內、一腳踏向前方，姿勢自然，不加入玻璃爆裂。", "fields": ["角色設定"], "image": "assets/images/38-A.webp", "imageStatus": "complete"}, {"id": "38-B", "category": "六、立體角色與微縮場景", "item": 38, "title": "黏土Q版角色", "variant": "B", "label": "新增一：閱讀黏土小人", "prompt": "請設計1:1黏土Q版閱讀角色，約兩頭身，戴圓框眼鏡，坐在巨大書本上抱著一本小書，旁邊有黏土植物與閱讀燈。使用奶油白、墨綠及暖橘，呈現手作黏土微紋、霧面材質與柔和棚拍光。主角表情專注可愛，書本與道具比例形成微縮趣味，背景簡潔，不生成書頁密集文字。", "fields": [], "image": "assets/images/38-B.webp", "imageStatus": "complete"}, {"id": "38-C", "category": "六、立體角色與微縮場景", "item": 38, "title": "黏土Q版角色", "variant": "C", "label": "新增二：職業黏土公仔", "prompt": "請依【職業與角色設定】設計4:5直式黏土Q版公仔，角色站在小型圓形底座，搭配三件具代表性的工作道具。採兩至三頭身、圓潤手腳與清楚服裝輪廓，保留角色識別特徵；使用柔和品牌色、霧面黏土及自然接觸陰影，背景像手作文創商品照。道具與職業相符，避免多餘手指及零件漂浮。", "fields": ["職業與角色設定"], "image": "assets/images/38-C.webp", "imageStatus": "complete"}, {"id": "39-A", "category": "六、立體角色與微縮場景", "item": 39, "title": "Q版角色踏出手機畫面", "variant": "A", "label": "優化版：立體透視突破", "prompt": "請製作4:5直式3D Q版角色踏出手機場景，角色為【設定】，採光滑樹脂公仔材質而非黏土。手機立於後景，螢幕內為【主題場景】，主角前腳踏出畫面、後腳仍在螢幕內；用低角度、前大後小與正確遮擋營造立體感。加入清楚接觸陰影與柔和輪廓光，人物可愛但四肢自然，背景不擁擠。", "fields": ["設定", "主題場景"], "image": "assets/images/39-A.webp", "imageStatus": "complete"}, {"id": "39-B", "category": "六、立體角色與微縮場景", "item": 39, "title": "Q版角色踏出手機畫面", "variant": "B", "label": "新增一：冒險角色登場", "prompt": "請設計3:2橫式3D Q版冒險角色登場圖，手機像通往森林世界的入口，主角背著背包跨出螢幕並向觀者招手。採青綠、暖黃與白色，前景放少量立體葉片，後景保持景深；光源由螢幕內延伸到外部，地面有自然投影。角色比例約三頭身，服裝與道具一致，不加入爆炸或密集碎片。", "fields": [], "image": "assets/images/39-B.webp", "imageStatus": "complete"}, {"id": "39-C", "category": "六、立體角色與微縮場景", "item": 39, "title": "Q版角色踏出手機畫面", "variant": "C", "label": "新增二：品牌角色送禮", "prompt": "請依【品牌角色參考】製作4:5直式3D角色圖，吉祥物從手機中的品牌活動頁跨出，雙手捧著【禮盒】。以透視及遮擋呈現禮盒比身體更靠近觀者，使用品牌色、乾淨棚拍背景與細膩塑膠材質。畫面內只顯示【指定活動短文案】，避免複雜介面，角色、手機與地面接觸關係合理。", "fields": ["品牌角色參考", "禮盒", "指定活動短文案"], "image": "assets/images/39-C.webp", "imageStatus": "complete"}, {"id": "40-A", "category": "六、立體角色與微縮場景", "item": 40, "title": "照片人物的3D迷你分身", "variant": "A", "label": "優化版：日常小分身", "prompt": "請以上傳人物照片為參考，製作4:5直式感性合成圖。保留真人主體的臉部、髮型與服裝，在桌面與肩膀周圍安排四個同一人物的3D Q版迷你分身，分別閱讀、喝咖啡、整理筆記與伸懶腰。使用暖色自然光，真人為攝影質感、分身為細緻公仔材質，比例、投影與視線合理，避免把小分身變成不同的人。", "fields": [], "image": "assets/images/40-A.webp", "imageStatus": "complete"}, {"id": "40-B", "category": "六、立體角色與微縮場景", "item": 40, "title": "照片人物的3D迷你分身", "variant": "B", "label": "新增一：工作桌上的分身", "prompt": "請依人物照片製作3:2橫式微縮工作情境，真人坐在筆電前，三個相同五官與服裝的小分身在鍵盤、便條紙與筆筒旁協助整理工作。採現代明亮辦公室、霧藍與暖白，微縮角色表情生動，人物手部自然。讓每個分身的接觸陰影與景深符合場景，保留真人人物辨識度，不添加多餘主角。", "fields": [], "image": "assets/images/40-B.webp", "imageStatus": "complete"}, {"id": "40-C", "category": "六、立體角色與微縮場景", "item": 40, "title": "照片人物的3D迷你分身", "variant": "C", "label": "新增二：學習中的自己", "prompt": "請以照片人物為中心，設計4:5直式「學習中的小分身」合成圖，真人正在閱讀，四個迷你Q版分身分別標記重點、提出問題、整理資料與展示成果。採暖白、墨綠及柔和黃，桌面有書本與筆記；分身保留相同髮型、五官與穿著。以真實光線統一人物與微縮場景，文字只放簡短主題【標題】。", "fields": ["標題"], "image": "assets/images/40-C.webp", "imageStatus": "complete"}, {"id": "41-A", "category": "六、立體角色與微縮場景", "item": 41, "title": "大尺寸與迷你版人物", "variant": "A", "label": "優化版：微縮夢境", "prompt": "請依上傳照片製作4:5直式溫暖微縮夢境，大尺寸人物與手掌中的迷你人物必須是同一人，五官、髮型及服裝一致。大人物坐在柔軟雲朵旁，輕輕托住正在揮手的縮小版自己，採奶油白、淡粉與霧藍，柔和日光及淺景深。兩者以接近寫實的材質呈現，尺寸差清楚，手掌承托、視線及陰影自然。", "fields": [], "image": "assets/images/41-A.webp", "imageStatus": "complete"}, {"id": "41-B", "category": "六、立體角色與微縮場景", "item": 41, "title": "大尺寸與迷你版人物", "variant": "B", "label": "新增一：咖啡杯旁的自己", "prompt": "請依人物照片設計3:2橫式微縮場景，真人坐在桌邊，迷你版自己坐在巨大咖啡杯邊緣閱讀，兩人五官與服裝完全一致。使用晨光、木桌與奶油色背景，真人面帶自然微笑，迷你人物姿勢穩定。透過景深、道具尺度與接觸陰影建立夢境感，杯子結構合理，避免迷你人物懸空或變成陌生人。", "fields": [], "image": "assets/images/41-B.webp", "imageStatus": "complete"}, {"id": "41-C", "category": "六、立體角色與微縮場景", "item": 41, "title": "大尺寸與迷你版人物", "variant": "C", "label": "新增二：與未來自己對話", "prompt": "請依同一張人物照片製作4:5直式象徵性肖像，較大人物蹲下與站在書本上的迷你自己對視，兩者保留同一張臉、髮型與衣著。背景是安靜工作室，暖光照亮人物，採灰藍、米白及少量橘色。強調鼓勵、成長與自我對話，構圖簡潔，視線高度與身體比例合理，不加入額外人物或長篇文字。", "fields": [], "image": "assets/images/41-C.webp", "imageStatus": "complete"}, {"id": "42-A", "category": "六、立體角色與微縮場景", "item": 42, "title": "照片人物衝破手機螢幕", "variant": "A", "label": "優化版：社群走入現實", "prompt": "請依上傳照片製作4:5直式高度寫實電影場景，人物從大型智慧型手機的社群貼文畫面跨入現實。保留臉部、髮型與服裝，手機中使用原創照片分享介面，前腳伸出螢幕、後半身仍在畫面內。採低角度透視、清楚輪廓光與少量玻璃碎片效果，碎片不遮臉；手腳結構、光影及遮擋合理，介面文字只用【指定內容】。", "fields": ["指定內容"], "image": "assets/images/42-A.webp", "imageStatus": "complete"}, {"id": "42-B", "category": "六、立體角色與微縮場景", "item": 42, "title": "照片人物衝破手機螢幕", "variant": "B", "label": "新增一：攝影世界跨界", "prompt": "請依人物照片製作3:2橫式寫實合成，人物從手機中的旅行照片走到桌面現實，螢幕內為【已提供的旅行場景】，螢幕外為簡潔攝影工作室。使用柔和電影光、自然膚色與明確前後景，人物保留原本五官，腳部跨越邊框、投影落在外部地面。以光與空間突破表現跨界，不使用破碎玻璃。", "fields": ["已提供的旅行場景"], "image": "assets/images/42-B.webp", "imageStatus": "complete"}, {"id": "42-C", "category": "六、立體角色與微縮場景", "item": 42, "title": "照片人物衝破手機螢幕", "variant": "C", "label": "新增二：舞台式亮相", "prompt": "請依照片人物製作4:5直式電影感主視覺，手機螢幕成為發光舞台入口，人物穿著【指定服裝】跨出畫面，背景為深色空間與柔和聚光燈。臉部辨識度維持，低角度但不誇大肢體，腳落在真實平台並產生接觸陰影。採黑、暖金及白色，保留上方【主標】位置，介面簡潔，不加入無關社群Logo。", "fields": ["指定服裝", "主標"], "image": "assets/images/42-C.webp", "imageStatus": "complete"}, {"id": "43-A", "category": "七、照片藝術轉換與個人風格", "item": 43, "title": "日系白邊手繪照片註解", "variant": "A", "label": "優化版：物件與手繪註解", "prompt": "請觀察上傳照片，保留原始人物、物件與場景，在主要物件外輪廓加入白色細手繪線，筆觸略不均勻、自然隨性。依可見內容為三至五個重點物件加入有意義的短註解、箭頭與小符號，像日系生活手帳。維持原照片比例，註解避開人物五官與商品標籤，不推測無法從照片確認的地點、品牌或心情。", "fields": [], "image": "assets/images/43-A.webp", "imageStatus": "complete"}, {"id": "43-B", "category": "七、照片藝術轉換與個人風格", "item": 43, "title": "日系白邊手繪照片註解", "variant": "B", "label": "新增一：咖啡生活註解", "prompt": "請將上傳咖啡桌照片製作4:5直式生活紀錄圖，保留飲品、甜點、桌面與手部的原樣，在杯子、餐盤與書本輪廓加入細白線，配上【提供的短句】。加入少量手繪蒸氣、星星與箭頭，整體溫暖自然，線條不遮住食物細節；若照片缺少留白，於邊緣增加乾淨註解區，不改造主要物件。", "fields": ["提供的短句"], "image": "assets/images/43-B.webp", "imageStatus": "complete"}, {"id": "43-C", "category": "七、照片藝術轉換與個人風格", "item": 43, "title": "日系白邊手繪照片註解", "variant": "C", "label": "新增二：旅行照片小筆記", "prompt": "請依上傳旅行照片加上日系白色手繪註解，保留真實風景與人物，圈出三個值得注意的視覺元素，搭配【日期、地名與觀察短句】。使用細線、簡單箭頭、波浪線與小型手寫標題，沿建築或山景局部描邊，不描滿全部邊界。維持原照片比例與構圖，地名只用提供資料，不添加不存在的景物。", "fields": ["日期、地名與觀察短句"], "image": "assets/images/43-C.webp", "imageStatus": "complete"}, {"id": "44-A", "category": "七、照片藝術轉換與個人風格", "item": 44, "title": "個人形象潑墨插圖", "variant": "A", "label": "優化版：日系水彩速寫", "prompt": "請以上傳人物照片為基礎，轉為4:5直式日系手繪肖像，保留臉部特徵、髮型、姿態與氣質。以鬆散墨線、淡水彩及局部塗鴉形成自然速寫感，主色為灰藍、奶茶棕與少量珊瑚橘；背景使用留白與細緻潑墨，臉部保持清楚。筆觸可自由但不扭曲五官，不將人物年齡或身份改成不同設定。", "fields": [], "image": "assets/images/44-A.webp", "imageStatus": "complete"}, {"id": "44-B", "category": "七、照片藝術轉換與個人風格", "item": 44, "title": "個人形象潑墨插圖", "variant": "B", "label": "新增一：黑白藝術肖像", "prompt": "請依人物照片製作3:4直式黑白墨線肖像，保留可辨識的眼睛、鼻形、嘴角、髮型與自然表情。以濃淡墨色、乾筆紋理及少量留白表現立體感，肩部與背景可用自由潑墨簡化，臉部則保持結構清楚。畫面像個人藝術展肖像，背景乾淨，不加入文字，不抹去人物真實特徵。", "fields": [], "image": "assets/images/44-B.webp", "imageStatus": "complete"}, {"id": "44-C", "category": "七、照片藝術轉換與個人風格", "item": 44, "title": "個人形象潑墨插圖", "variant": "C", "label": "新增二：彩色塗鴉形象", "prompt": "請依人物照片設計1:1彩色手繪形象圖，保留人物五官與髮型，結合水彩、彩鉛與輕鬆塗鴉。周圍加入與【個人興趣】相關的三個小圖案，使用明亮藍、暖黃與粉橘，背景留白。人物胸像為焦點，圖案不遮臉，整體有活力與個性，不依照片擅自推測職業或興趣。", "fields": ["個人興趣"], "image": "assets/images/44-C.webp", "imageStatus": "complete"}, {"id": "45-A", "category": "七、照片藝術轉換與個人風格", "item": 45, "title": "角色設定海報", "variant": "A", "label": "優化版：日系寫實角色設定", "prompt": "請依上傳人物照片製作A4直式日系寫實插畫角色設定海報，保留五官、髮型與整體氣質。中央為全身主視覺，側邊放正面頭像、側面頭像及兩種表情，底部放【姓名、角色背景、配色設定】。使用細緻數位手繪與乾淨灰白背景，各視角維持同一人物，服裝依照片或指定設定，不把推測性背景寫成事實。", "fields": ["姓名、角色背景、配色設定"], "image": "assets/images/45-A.webp", "imageStatus": "complete"}, {"id": "45-B", "category": "七、照片藝術轉換與個人風格", "item": 45, "title": "角色設定海報", "variant": "B", "label": "新增一：職業角色設定", "prompt": "請依照片與【職業設定】製作3:2橫式人物設定板，左側為全身角色，中間為三個表情，右側展示兩件工作道具及服裝細節。採半寫實數位插畫、柔和品牌色及白底，保留原五官、髮型與身形辨識度。文字只放【角色名稱與提供的設定】，不同視角比例一致，不新增不存在的制服徽章或資格。", "fields": ["職業設定", "角色名稱與提供的設定"], "image": "assets/images/45-B.webp", "imageStatus": "complete"}, {"id": "45-C", "category": "七、照片藝術轉換與個人風格", "item": 45, "title": "角色設定海報", "variant": "C", "label": "新增二：奇幻化身設定", "prompt": "請依人物照片設計A4直式原創奇幻角色設定海報，保留可辨識五官與髮型，將服裝改為【指定奇幻職業】。中央呈現全身角色，左右展示武器或工具、服裝細節與三個表情，背景簡潔，配色為【指定色系】。角色形象一致，道具符合世界觀，文字依【角色設定】填入，不使用既有動漫角色服飾或標誌。", "fields": ["指定奇幻職業", "指定色系", "角色設定"], "image": "assets/images/45-C.webp", "imageStatus": "complete"}, {"id": "46-A", "category": "七、照片藝術轉換與個人風格", "item": 46, "title": "穿搭建議分析", "variant": "A", "label": "優化版：個人風格解析", "prompt": "請依人物照片設計A4直式穿搭建議海報，先以文字整理照片可觀察的臉部輪廓、服裝比例與整體風格，再呈現三套可嘗試的穿搭。照片可能受角度與光線影響，身形比例及膚色判讀請標示為視覺建議；依【場合、喜好、預算】安排服裝、配色與鞋款，保留人物五官，不以單張照片斷定精確尺寸或膚色分類。", "fields": ["場合、喜好、預算"], "image": "assets/images/46-A.webp", "imageStatus": "complete"}, {"id": "46-B", "category": "七、照片藝術轉換與個人風格", "item": 46, "title": "穿搭建議分析", "variant": "B", "label": "新增一：教師工作穿搭", "prompt": "請依上傳照片及【穿搭偏好】設計3:2橫式教師工作穿搭板，展示日常授課、正式會議與研習講師三種情境。保持同一人物臉部與自然體態，以整潔、方便活動的服裝搭配鞋款與配件；使用米白、深藍及暖棕，標示各套的場合與配色重點。建議以照片可見特徵為依據，不改造身材或虛構衣物尺碼。", "fields": ["穿搭偏好"], "image": "assets/images/46-B.webp", "imageStatus": "complete"}, {"id": "46-C", "category": "七、照片藝術轉換與個人風格", "item": 46, "title": "穿搭建議分析", "variant": "C", "label": "新增二：旅行膠囊衣櫥", "prompt": "請依人物照片及【旅行季節、地點、天數、偏好】設計A4直式旅行穿搭板，挑選【指定件數】衣物組成三套搭配。上方保留人物形象，下方展示上衣、外套、褲裙與鞋款的排列及組合，採乾淨雜誌排版與柔和配色。款式兼顧行走與活動，保留真實五官及體態，溫度與天氣條件只使用提供資料。", "fields": ["旅行季節、地點、天數、偏好", "指定件數"], "image": "assets/images/46-C.webp", "imageStatus": "complete"}, {"id": "47-A", "category": "七、照片藝術轉換與個人風格", "item": 47, "title": "復古電子寵物像素風", "variant": "A", "label": "優化版：90年代LCD畫面", "prompt": "請將上傳圖片轉為1:1復古電子寵物機畫面，主體簡化為低解析像素形狀，保留最具辨識度的輪廓與姿態。使用單色灰綠LCD、清楚像素網格與四級明暗，搭配原創蛋形機身及三個實體按鈕。像素邊緣保持硬邊，不加平滑寫實陰影；狀態圖示簡潔，文字只使用【指定短文字】。", "fields": ["指定短文字"], "image": "assets/images/47-A.webp", "imageStatus": "complete"}, {"id": "47-B", "category": "七、照片藝術轉換與個人風格", "item": 47, "title": "復古電子寵物像素風", "variant": "B", "label": "新增一：掌上遊戲人物卡", "prompt": "請依上傳人物照片製作3:2橫式復古掌上遊戲角色卡，人物以清楚低解析像素呈現，保留髮型、服裝與代表性表情。使用有限的八至十二色調色盤，加入原創遊戲視窗、角色名稱【名稱】與三個提供的屬性欄。像素方格一致、邊緣不模糊，避免使用現有遊戲角色或未提供的能力數值。", "fields": ["名稱"], "image": "assets/images/47-B.webp", "imageStatus": "complete"}, {"id": "47-C", "category": "七、照片藝術轉換與個人風格", "item": 47, "title": "復古電子寵物像素風", "variant": "C", "label": "新增二：像素生活場景", "prompt": "請將上傳生活照片轉為1:1復古像素插畫，保留主要人物、物件位置與場景結構，以有限色盤、階梯式輪廓與少量像素抖色呈現。風格像早期生活模擬遊戲，主體清楚，背景細節適度簡化；不加入寫實光暈或柔焦，照片中無法辨認的文字改為空白像素牌，不自行生成品牌與內容。", "fields": [], "image": "assets/images/47-C.webp", "imageStatus": "complete"}, {"id": "48-A", "category": "七、照片藝術轉換與個人風格", "item": 48, "title": "照片電影海報風", "variant": "A", "label": "優化版：敘事電影主視覺", "prompt": "請將上傳照片轉為2:3直式原創電影海報，電影類型為【類型】，片名為【片名】。保留主角五官、髮型與辨識度，依【故事概念】加入有敘事意義的背景與光影，建立主角、環境及標題三層。採戲劇性側光、自然膚色與細緻底片顆粒，下方放【提供的演職員或上映資訊】，不虛構獎項與影展標誌。", "fields": ["類型", "片名", "故事概念", "提供的演職員或上映資訊"], "image": "assets/images/48-A.webp", "imageStatus": "complete"}, {"id": "48-B", "category": "七、照片藝術轉換與個人風格", "item": 48, "title": "照片電影海報風", "variant": "B", "label": "新增一：溫暖人生電影", "prompt": "請依人物照片設計2:3直式溫暖劇情片海報，主角保留原本臉部與神情，站在黃昏街道或窗邊，遠景加入【故事相關元素】。使用暖金、奶油白與低彩度藍，柔和側光，營造陪伴與成長。上方留一句【宣傳短句】，下方放【片名與指定資訊】，畫面安靜有情感，不加入無關演員姓名。", "fields": ["故事相關元素", "宣傳短句", "片名與指定資訊"], "image": "assets/images/48-B.webp", "imageStatus": "complete"}, {"id": "48-C", "category": "七、照片藝術轉換與個人風格", "item": 48, "title": "照片電影海報風", "variant": "C", "label": "新增二：懸疑調查電影", "prompt": "請依人物照片製作2:3直式懸疑電影海報，保留人物五官，主角位於前景，後方是雨夜城市、模糊文件與一束光，依【故事設定】安排線索。採深藍、灰黑與少量暖紅，強烈明暗但臉部可辨識。片名【名稱】清楚置於下方，短句置上方，線索不過量，避免血腥細節與虛構影展榮譽。", "fields": ["故事設定", "名稱"], "image": "assets/images/48-C.webp", "imageStatus": "complete"}, {"id": "49-A", "category": "七、照片藝術轉換與個人風格", "item": 49, "title": "日本極道千金／少爺風", "variant": "A", "label": "優化版：黑色轎車登場", "prompt": "請依上傳成年人物照片製作4:5直式日本犯罪電影風格肖像，保留原五官、髮型與自然體態。主角穿深色俐落套裝，站在打開的黑色高級轎車車門前，一位保鑣撐黑傘、另一位在遠處警戒。採雨夜街道、低角度與黑金光影，氣質沉穩有張力，雨水反射自然；不出現武器或幫派標誌，也不把虛構造型當成真實身份。", "fields": [], "image": "assets/images/49-A.webp", "imageStatus": "complete"}, {"id": "49-B", "category": "七、照片藝術轉換與個人風格", "item": 49, "title": "日本極道千金／少爺風", "variant": "B", "label": "新增一：日式宅邸權力感", "prompt": "請依成年人物照片製作2:3直式原創犯罪劇肖像，人物穿著剪裁俐落的深色西裝，坐在日式宅邸的木質長廊，背景為雨庭、紙門與低調保鑣輪廓。保留五官、髮型與體態，採深棕、黑色及暖金，側光與留白營造冷靜氣場。角色屬虛構電影設定，不加入武器、暴力場景或現實組織識別。", "fields": [], "image": "assets/images/49-B.webp", "imageStatus": "complete"}, {"id": "49-C", "category": "七、照片藝術轉換與個人風格", "item": 49, "title": "日本極道千金／少爺風", "variant": "C", "label": "新增二：都市雨夜主角", "prompt": "請以成年人物照片為參考，製作4:5直式都市犯罪劇主角海報，人物穿黑色長外套，站在濕潤巷口，後方是模糊霓虹與黑色車輛。保留原五官與髮型，目光沉穩，使用深藍、黑色與少量酒紅，電影感輪廓光及真實雨水質感。上方預留【原創片名】，不加入武器或真實幫派符號。", "fields": ["原創片名"], "image": "assets/images/49-C.webp", "imageStatus": "complete"}, {"id": "50-A", "category": "七、照片藝術轉換與個人風格", "item": 50, "title": "Y2K四格大頭貼", "variant": "A", "label": "優化版：電梯魚眼自拍", "prompt": "請依上傳人物照片製作1:1整體比例、2×2四格拼貼大頭貼，每格皆為同一人物在有鏡子的電梯內自拍，分別微笑、比手勢、驚訝與輕鬆側身。保留五官、髮型與服裝，採適度魚眼、直閃、銀灰與亮粉色，加入少量原創星星貼紙及【短文字】。鏡像與手機位置合理，不因鏡頭效果過度扭曲臉部。", "fields": ["短文字"], "image": "assets/images/50-A.webp", "imageStatus": "complete"}, {"id": "50-B", "category": "七、照片藝術轉換與個人風格", "item": 50, "title": "Y2K四格大頭貼", "variant": "B", "label": "新增一：復古拍貼機", "prompt": "請依人物照片製作2:3直式四格拍貼帶，四格由上至下，人物五官與服裝一致，表情為微笑、眨眼、比心及大笑。採奶油白、淡粉與天藍背景，加入Y2K亮面小貼紙、泡泡字與日期【提供日期】，保留清楚臉部。四格光線一致、手部自然，邊框有拍貼機感，不加入現有品牌標誌。", "fields": ["提供日期"], "image": "assets/images/50-B.webp", "imageStatus": "complete"}, {"id": "50-C", "category": "七、照片藝術轉換與個人風格", "item": 50, "title": "Y2K四格大頭貼", "variant": "C", "label": "新增二：銀色未來自拍拼貼", "prompt": "請依人物照片設計1:1四格Y2K自拍拼貼，背景為銀色電梯或原創未來感空間，每格保持同一人，以不同角度與輕鬆姿態呈現。使用直閃攝影、銀灰、冰藍及螢光綠點綴，加入少量金屬星形、日期【日期】與短標題【文案】。保持自然五官、合理鏡像與清楚分格，裝飾不遮住眼睛或嘴部。", "fields": ["日期", "文案"], "image": "assets/images/50-C.webp", "imageStatus": "complete"}];
